fun parsePositiveAmount(text: String): Double? {
    val amount = text.trim().toDoubleOrNull()
    return if (amount != null && amount > 0.0) amount else null
}

fun main() {
    val amount = parsePositiveAmount(" 12.50 ")
    val message = if (amount == null) "Enter a positive number" else "Accepted: £$amount"
    println(message)
}

