fun amountMessage(raw: String?): String {
    val amount = raw?.trim()?.toDoubleOrNull()
    return when {
        amount == null -> "Enter a number"
        amount <= 0.0 -> "Amount must be positive"
        else -> "Accepted: £$amount"
    }
}

fun main() {
    println(amountMessage("18.75"))
    println(amountMessage("free"))
}
